export const MALWARE_PRESETS={
 virus:{name:'File virus',marker:'HEXLAB_DEMO_VIRUS',effect:'mark',spread:2,description:'파일에 감염 표시를 추가하는 바이러스 개념 모델',source:'https://www.cisa.gov/sites/default/files/publications/aa22-216a-2021-top-malware-strains.pdf'},
 wannacry:{name:'WannaCry · concept',marker:'HEXLAB_DEMO_WANNACRY',effect:'lock',spread:3,description:'웜 확산과 파일 접근 불가를 표현합니다. 실제 암호화·SMB 공격은 실행하지 않습니다.',source:'https://www.microsoft.com/en-us/security/blog/2017/05/12/wannacrypt-ransomware-worm-targets-out-of-date-systems/'},
 worm:{name:'Worm · concept',marker:'HEXLAB_DEMO_WORM',effect:'replicate',spread:4,description:'사용자 개입 없이 가상 파일 사이로 확산되는 개념 모델',source:'https://www.cisa.gov/sites/default/files/publications/aa22-216a-2021-top-malware-strains.pdf'},
 trojan:{name:'Trojan · concept',marker:'HEXLAB_DEMO_TROJAN',effect:'mark',spread:1,description:'유용해 보이는 파일에 숨은 감염 표시를 넣는 개념 모델',source:'https://www.cisa.gov/sites/default/files/publications/aa22-216a-2021-top-malware-strains.pdf'},
 custom:{name:'My demo virus',marker:'HEXLAB_CUSTOM',effect:'mark',spread:2,description:'직접 만드는 가상 악성코드 동작 규칙',source:null}
};
export function createVirtualFiles(){return[{name:'index.html',content:'<h1>Welcome to HEXLAB</h1>'},{name:'config.json',content:'{"theme":"green"}'},{name:'invoice.pdf',content:'VIRTUAL_PDF_INVOICE'},{name:'notes.txt',content:'Project notes and ideas'},{name:'photo.png',content:'VIRTUAL_PNG_IMAGE'},{name:'backup.zip',content:'VIRTUAL_ZIP_BACKUP'},{name:'setup.exe',content:'VIRTUAL_EXECUTABLE_LABEL_ONLY'},{name:'users.csv',content:'name,role\ndemo,guest'}].map(f=>({...f,original:f.content,infected:false,locked:false,quarantined:false,detected:false,events:[]}));}
export function validateVirus(config){if(!config||typeof config.name!=='string'||config.name.length<1||config.name.length>60||typeof config.marker!=='string'||config.marker.length<3||config.marker.length>80||!Number.isInteger(config.spread)||config.spread<1||config.spread>8||!['mark','lock','replicate'].includes(config.effect))throw new Error('이름·표시자·동작을 확인하세요. spread는 1–8 정수여야 합니다.');return config;}
export function infectFiles(files,config){validateVirus(config);let count=0;const next=files.map(f=>{if(f.infected||f.quarantined||count>=config.spread)return{...f,events:[...f.events]};count++;return{...f,content:f.content+'\n'+config.marker,infected:true,locked:config.effect==='lock',events:[...f.events,config.effect==='lock'?'file_lock':config.effect==='replicate'?'replication':'file_write']};});return{files:next,infected:count};}
export function validateRules(rules){if(!Array.isArray(rules)||!rules.length||rules.length>20)throw new Error('탐지 규칙은 1–20개의 배열이어야 합니다.');for(const r of rules){if(typeof r.name!=='string'||r.name.length>80||!['signature','behavior'].includes(r.type)||typeof r.match!=='string'||!r.match||r.match.length>120||!['quarantine','report'].includes(r.action))throw new Error('각 규칙에 name, type, match, action을 올바르게 지정하세요.');}return rules;}
export function scanVirtualFiles(files,rules){validateRules(rules);let detected=0;let quarantined=0;const results=[];const next=files.map(f=>{if(f.quarantined)return{...f};const rule=rules.find(r=>r.type==='signature'?f.content.includes(r.match):f.events.includes(r.match));if(!rule)return{...f,detected:false};detected++;const q=rule.action==='quarantine';if(q)quarantined++;results.push({name:f.name,rule:rule.name,action:rule.action});return{...f,detected:true,quarantined:q};});return{files:next,detected,quarantined,results};}
export function restoreVirtualFiles(files){return files.map(f=>({...f,content:f.original,infected:false,locked:false,quarantined:false,detected:false,events:[]}));}
export function inspectCode({html,css,js}){const issues=[];const add=(id,severity,title,description,evidence,fix)=>issues.push({id,severity,title,description,evidence,fix});if(/\.innerHTML\s*=|document\.write\s*\(/.test(js))add('sink','high','Unsafe HTML Sink','HTML을 직접 삽입하는 코드가 있습니다. 입력의 신뢰도를 확인하세요.','innerHTML assignment / document.write','일반 텍스트는 textContent로 출력하세요. 필요한 HTML은 검증된 정화 도구를 사용하세요.');if(/\beval\s*\(|new\s+Function\s*\(/.test(js))add('eval','high','Dynamic Code Execution','문자열을 코드로 실행하는 구문이 있습니다.','eval / new Function','문자열 코드 실행을 제거하고 명시적인 함수 호출을 사용하세요.');if(/\b(?:api[_-]?key|secret|password)\s*[:=]\s*["'][^"']{4,}["']/i.test(js+html))add('secret','medium','Potential Hardcoded Secret','클라이언트 소스에 비밀 값으로 보이는 문자열이 있습니다.','keyword and string pattern matched; value hidden','실제 비밀은 서버에서 보관하고, 노출된 키는 교체하세요.');if(/<form\b/i.test(html)&&!/csrf/i.test(html))add('csrf','info','Form Requires Manual Review','폼이 있습니다. CSRF 보호 여부는 서버에서 확인해야 합니다.','HTML form observed; protection cannot be verified','변경 요청의 CSRF 토큰과 SameSite 정책을 서버에서 확인하세요.');if(/<script\b/i.test(html))add('embedded-script','info','Embedded Script Removed in Preview','HTML 안의 스크립트는 미리보기에서 제거됩니다.','script element observed','실행할 실습 코드는 JS 탭에 작성하세요.');return issues;}
